-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$PCB - Stencil Print$q$, 7, 1),
    ($q$PCB - Solder Paste Inspection$q$, 8, 1),
    ($q$PCB - Pick and Place$q$, 6, 1),
    ($q$PCB - Reflow Solder$q$, 10, 1),
    ($q$PCB - Assembly AOI$q$, 8, 1),
    ($q$PCB - THT Insertion$q$, 4, 1),
    ($q$PCB - Wave Solder$q$, 7, 1),
    ($q$PCB - Selective Solder$q$, 4, 1),
    ($q$PCB - Hand Solder$q$, 4, 1),
    ($q$PCB - In-Circuit Test$q$, 6, 1),
    ($q$PCB - Assembly Flying Probe$q$, 6, 1),
    ($q$PCB - Depanel Router$q$, 4, 1),
    ($q$PCB - SMT line changeover$q$, 8, 0),
    ($q$PCB - SMT line balance$q$, 5, 0),
    ($q$PCB - Solder paste$q$, 6, 0),
    ($q$PCB - ICT fixture$q$, 4, 0)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$PCB$q$ AND (m.is_active OR m.machine_class IS NULL)) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1134: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
